from .base_cl_tool import BaseClToolInterface


class SFPMonitorInterface(BaseClToolInterface):
    """Keyword for SFP monitoring related commands."""

    def start_sfp_monitor(self, duration, timeout='5min', flags=None, **kwargs):
        """
        Execute SFP monitor and generate result.

        :param int duration: Test duration (default is 2min and format is the same as timeout)

        |

        :Supported flag:
            * **xml** -                     If set, will generate the result in XML format.

        |
        :return: Path(s) of collected file(s).
        :rtype: list
        """

        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        duration = self._convert_to_secs(duration)
        params = {'ne': ne, 'pw': pw, 'duration': duration, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = flags.replace(' ', '').split(',') if flags else []
        if nolog:
            flags.append('nolog')
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='sfpmonitor', params=params, trs_ip=ne, flags=flags)
